package glitch

import data.glitch_lib

import future.keywords.in

# Network-related attribute/variable name patterns
network_name_patterns := ["bind", "listen", "host", "address", "ip", "interface", "bindip", "bind_ip", "bindaddress", "bind_address", "bindaddr", "listen_address", "listeninterface", "listen_ip", "listenaddr", "source", "destination", "cidr", "subnet", "network"]

# Open network binding values (0.0.0.0, ::, etc.)
open_bind_pattern := "(?i)^\\s*(0\\.0\\.0\\.0(/0)?|::(/0)?|\\*|all|any|0000:0000:0000:0000:0000:0000:0000:0000)\\s*$"

# Helper to check if a feature is in a set
network_name_matches(name) {
    some pattern in network_name_patterns
    regex.match(sprintf(".*%s.*", [pattern]), lower(name))
}

# Flatten Hash to find all leaf string values
hash_leaves_to_strings(node) = strings {
    node.ir_type == "Hash"
    strings := [s |
        some k, v in node.value
        s := _value_to_strings(v)
    ]
}

_value_to_strings(v) = [v.value] {
    v.ir_type == "String"
}

_value_to_strings(v) = arr {
    v.ir_type == "Array"
    arr := [s |
        some elem in v.value
        s := _value_to_strings(elem)[_]
    ]
}

_value_to_strings(v) = arr {
    v.ir_type == "Hash"
    arr := [s |
        some elem in hash_leaves_to_strings(v)
        s := elem
    ]
}

_value_to_strings(v) = [] {
    not v.ir_type in {"String", "Array", "Hash"}
}

# Check if any string in the flattened structure matches open bind pattern
has_open_bind(node) {
    node.ir_type == "String"
    regex.match(open_bind_pattern, node.value)
}

has_open_bind(node) {
    node.ir_type == "Array"
    some elem in node.value
    has_open_bind(elem)
}

has_open_bind(node) {
    node.ir_type == "Hash"
    some k, v in node.value
    has_open_bind(v)
}

# Check variables in unit blocks
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    vars := glitch_lib.all_variables(parent)
    var := vars[_]

    network_name_matches(var.name)
    has_open_bind(var.value)

    result := {
        "type": "sec_invalid_bind",
        "element": var,
        "path": parent.path,
        "description": "Improper Access Control - Network service bound to 0.0.0.0 or equivalent, exposing it to all network interfaces. (CWE-284)"
    }
}

# Check attributes in atomic units
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    network_name_matches(attr.name)
    has_open_bind(attr.value)

    result := {
        "type": "sec_invalid_bind",
        "element": attr,
        "path": parent.path,
        "description": "Improper Access Control - Network service bound to 0.0.0.0 or equivalent, exposing it to all network interfaces. (CWE-284)"
    }
}

